-- Lab-only example: create a dedicated temporary tenant table.
DROP TABLE IF EXISTS tenant_documents_lab;
CREATE TEMP TABLE tenant_documents_lab (document_id integer PRIMARY KEY, tenant_id integer NOT NULL, body text NOT NULL);
INSERT INTO tenant_documents_lab VALUES (1, 1, 'Tenant one'), (2, 2, 'Tenant two');
ALTER TABLE tenant_documents_lab ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant_documents_lab FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_documents_isolation ON tenant_documents_lab USING (tenant_id = current_setting('app.tenant_id', true)::integer) WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::integer);
SET app.tenant_id = '1';
SELECT * FROM tenant_documents_lab;
RESET app.tenant_id;
DROP TABLE tenant_documents_lab;
